def edit(doc):
    from collections import defaultdict
    counters = defaultdict(int)
    result = {}
    for o in doc.Objects:
        if o.TypeId.startswith(('PartDesign::', 'Sketcher::')):
            type_short = o.TypeId.split('::')[-1]
            counters[type_short] += 1
            new_label = f"{type_short}_{counters[type_short]}"
            if o.Label != new_label:
                o.Label = new_label
                result[o.Name] = new_label
    return result if result else None

def edit(doc):
    # Find all PartDesign Pad objects
    pads = [o for o in doc.Objects if o.TypeId == 'PartDesign::Pad']
    if not pads:
        return {"removed": []}

    # Create or get the Dims VarSet
    dims = doc.getObject('Dims')
    if dims is None:
        dims = doc.addObject('App::VarSet', 'Dims')

    # For each pad, create a property and bind the Length expression
    for pad in pads:
        # Create a unique property name based on pad label
        prop_name = pad.Label.replace(' ', '_').replace('-', '_')
        # Ensure property name is valid (no leading digit, no special chars)
        if not prop_name or prop_name[0].isdigit():
            prop_name = 'Pad_' + prop_name
        # Add property if it doesn't exist
        if not hasattr(dims, prop_name):
            dims.addProperty('App::PropertyLength', prop_name, 'PadLengths', 'Length for ' + pad.Label)
        # Set the property value to current pad length
        setattr(dims, prop_name, pad.Length)
        # Bind pad Length to the VarSet property via expression
        pad.setExpression('Length', u'Dims.' + prop_name)

    return {"count": len(pads)}

def edit(doc):
    # Create VarSet if it doesn't exist
    var_set = doc.getObject('Dims')
    if var_set is None:
        var_set = doc.addObject('App::VarSet', 'Dims')

    # Process each Pad object
    pads = [o for o in doc.Objects if o.TypeId == 'PartDesign::Pad']
    for pad in pads:
        # Create a unique property name based on pad label
        prop_name = pad.Label.replace(' ', '_').replace('-', '_')
        if not prop_name or prop_name[0].isdigit():
            prop_name = 'Pad_' + prop_name

        # Add property to VarSet if it doesn't exist
        if not hasattr(var_set, prop_name):
            var_set.addProperty('App::PropertyLength', prop_name, 'PadLengths')

        # Set the property value to match current pad length
        setattr(var_set, prop_name, pad.Length)

        # Bind pad Length to VarSet property via expression
        pad.setExpression('Length', f'Dims.{prop_name}')

    return {"count": len(pads)}

