def edit(doc):
    import re
    # Collect all PartDesign and Sketcher objects in document order
    target_objects = []
    for o in doc.Objects:
        if o.TypeId.startswith(('PartDesign::', 'Sketcher::')):
            target_objects.append(o)
    # Group by the type suffix (after '::')
    type_groups = {}
    for o in target_objects:
        suffix = o.TypeId.split('::')[-1]
        if suffix not in type_groups:
            type_groups[suffix] = []
        type_groups[suffix].append(o)
    # Assign labels with incrementing counters per type
    for suffix, objs in type_groups.items():
        for i, o in enumerate(objs, start=1):
            o.Label = f"{suffix}_{i}"
    return None

