def edit(doc):
    # Find the Pad object
    pad = None
    for obj in doc.Objects:
        if obj.TypeId == 'PartDesign::Pad':
            pad = obj
            break
    if pad is None:
        return {"removed": []}

    # Get or create the Dims VarSet
    dims = doc.getObject('Dims')
    if dims is None:
        dims = doc.addObject('App::VarSet', 'Dims')

    # Determine a property name for this pad
    prop_name = pad.Label.replace(' ', '_') + '_Length'

    # Add property if it doesn't exist
    if not hasattr(dims, prop_name):
        dims.addProperty('App::PropertyLength', prop_name, 'Dimensions', 'Length of pad')

    # Set the property value from pad's current Length
    length_value = pad.Length
    setattr(dims, prop_name, length_value)

    # Bind pad's Length to the Dims property via expression
    pad.setExpression('Length', u'Dims.' + prop_name)

    return {"removed": []}

