def edit(doc):
    """Rename all Sketch objects to start with 'Sk_'."""
    changes = {}
    for obj in doc.Objects:
        if obj.TypeId == 'Sketcher::SketchObject':
            if not obj.Label.startswith('Sk_'):
                old_label = obj.Label
                obj.Label = 'Sk_' + old_label
                changes[old_label] = obj.Label
    return {"relabeled": changes} if changes else None

