def edit(doc):
    import re

    # Find all PartDesign::Pad objects
    pads = [o for o in doc.Objects if o.TypeId == 'PartDesign::Pad']
    if not pads:
        return {"removed": []}

    # Create or get the "Dims" spreadsheet
    dims = doc.getObject('Dims')
    if dims is None:
        dims = doc.addObject('Spreadsheet::Sheet', 'Dims')
        dims.Label = 'Dims'

    # For each pad, create an alias and bind Length
    for pad in pads:
        # Create a safe alias from the pad's name
        alias = re.sub(r'[^a-zA-Z0-9_]', '_', pad.Name)
        if not alias or alias[0].isdigit():
            alias = 'A_' + alias

        # Find next empty row in spreadsheet
        row = 1
        while True:
            cell = f'A{row}'
            if not dims.getContents(cell):
                break
            row += 1

        # Set the value and alias
        dims.set(cell, str(pad.Length))
        dims.setAlias(cell, alias)

        # Bind pad's Length to the spreadsheet cell
        pad.setExpression('Length', f'Dims.{alias}')

    return {"count": len(pads)}

