def edit(doc):
    import FreeCAD

    result = {}

    # Find all PartDesign bodies
    bodies = [o for o in doc.Objects if o.TypeId == 'PartDesign::Body']

    for body in bodies:
        body_name = body.Name
        body_label = body.Label

        # Create a parameter container for this body
        container = doc.addObject('Spreadsheet::Sheet', f'Params_{body_name}')
        container.Label = f'{body_label} Parameters'

        # Get all features in this body
        features = body.Group

        # Find candidate literals to lift
        candidates = refactor.lift_candidates(doc)

        # Filter candidates belonging to this body's features
        body_candidates = []
        for cand in candidates:
            obj_name = cand['object']
            obj = doc.getObject(obj_name)
            if obj and obj in features:
                body_candidates.append(cand)

        # Lift literals for this body into its container
        for cand in body_candidates:
            obj_name = cand['object']
            prop = cand['property']
            obj = doc.getObject(obj_name)
            if obj:
                try:
                    refactor.lift_literal(doc, obj_name, prop, target='Spreadsheet', container=container.Label)
                except Exception:
                    pass

        # Apply across bodies for this body's features (parameterise)
        refactor.apply_across_bodies(doc, lambda b: b if b.Name == body_name else None)

    # Also lift all candidates globally into appropriate containers
    all_candidates = refactor.lift_candidates(doc)
    for cand in all_candidates:
        obj_name = cand['object']
        prop = cand['property']
        obj = doc.getObject(obj_name)
        if obj:
            # Find which body this object belongs to
            parent_body = None
            for body in bodies:
                if obj in body.Group:
                    parent_body = body
                    break
            if parent_body:
                container_name = f'Params_{parent_body.Name}'
                try:
                    refactor.lift_literal(doc, obj_name, prop, target='Spreadsheet', container=container_name)
                except Exception:
                    pass

    # Return result
    return {"refactored": True}

