def edit(doc):
    # Ensure a VarSet container exists
    params = doc.getObject('Parameters')
    if params is None:
        params = doc.addObject('App::VarSet', 'Parameters')
    params.Label = 'Parameters'

    # Lift all candidate literals into the VarSet
    result = refactor.lift_all(doc, target='VarSet', container='Parameters', limit=None)

    # Ensure the VarSet object is accessible by name
    if doc.getObject('Parameters') is None:
        # Fallback: rename if needed (should not happen)
        for obj in doc.Objects:
            if obj.TypeId == 'App::VarSet' and obj.Label == 'Parameters':
                obj.Label = 'Parameters'
                break

    return result

