def edit(doc):
    import re
    target_types = ('PartDesign::', 'Sketcher::')
    counters = {}
    for obj in doc.Objects:
        for prefix in target_types:
            if obj.TypeId.startswith(prefix):
                suffix = obj.TypeId.split('::')[-1]
                counters[suffix] = counters.get(suffix, 0) + 1
                new_label = f"{suffix}_{counters[suffix]}"
                if obj.Label != new_label:
                    obj.Label = new_label
                break
    return None

def edit(doc):
    # Collect all objects of PartDesign:: and Sketcher:: types in document order
    objs = [o for o in doc.Objects if o.TypeId.startswith(('PartDesign::', 'Sketcher::'))]
    # Count per type suffix (the part after '::')
    counts = {}
    for o in objs:
        suffix = o.TypeId.split('::')[-1]
        counts[suffix] = counts.get(suffix, 0) + 1
        o.Label = f"{suffix}_{counts[suffix]}"
    return None

def edit(doc):
    # Collect all PartDesign and Sketcher objects in document order
    objects = []
    for o in doc.Objects:
        if o.TypeId.startswith(('PartDesign::', 'Sketcher::')):
            objects.append(o)

    # Count per type and assign labels
    counts = {}
    for o in objects:
        type_short = o.TypeId.split('::')[-1]
        counts[type_short] = counts.get(type_short, 0) + 1
        new_label = f"{type_short}_{counts[type_short]}"
        o.Label = new_label

    return None

def edit(doc):
    import re
    from collections import defaultdict

    counters = defaultdict(int)
    changes = {}

    for obj in doc.Objects:
        if obj.TypeId.startswith(('PartDesign::', 'Sketcher::')):
            type_name = obj.TypeId.split('::')[-1]
            counters[type_name] += 1
            new_label = f"{type_name}_{counters[type_name]}"
            if obj.Label != new_label:
                obj.Label = new_label
                changes[obj.Name] = new_label

    if changes:
        return {"relabeled": changes}
    return None

def edit(doc):
    counts = {}
    for obj in doc.Objects:
        if obj.TypeId.startswith(('PartDesign::', 'Sketcher::')):
            base = obj.TypeId.split('::')[-1]
            counts.setdefault(base, 0)
            counts[base] += 1
            obj.Label = f"{base}_{counts[base]}"
    return None

def edit(doc):
    # Find all PartDesign::Pad objects
    pads = [o for o in doc.Objects if o.TypeId == 'PartDesign::Pad']
    if not pads:
        return None

    # Create or get the Dims VarSet
    dims = doc.getObject('Dims')
    if dims is None:
        dims = doc.addObject('App::VarSet', 'Dims')

    # For each pad, create a property in Dims and bind expression
    for pad in pads:
        prop_name = pad.Label + '_Length'
        # Add property if not already present
        if not hasattr(dims, prop_name):
            dims.addProperty('App::PropertyLength', prop_name, 'PadLengths', f'Length for {pad.Label}')
        # Set the property value to the current pad length
        setattr(dims, prop_name, pad.Length)
        # Bind pad's Length to the Dims property via expression
        pad.setExpression('Length', f'Dims.{prop_name}')

    return {"count": len(pads)}

